import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class InventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("InventoryServlet");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("detail".equals(action)) {
            handleDetail(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String category = req.getParameter("category");
        String sortCol = req.getParameter("sort");
        if (sortCol == null) sortCol = "name";

        // Whitelist sort columns to prevent injection there
        if (!sortCol.matches("^(name|price|stock|created_at)$")) {
            sortCol = "name";
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Category filter uses string concatenation for LIKE clause
            String sql = "SELECT id, name, price, stock FROM inventory " +
                         "WHERE category LIKE '%" + category + "%' " +
                         "ORDER BY " + sortCol + " ASC LIMIT 50";
            log.info("Executing query: " + sql);

            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql);

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append(String.format(
                    "  {\"id\": %d, \"name\": \"%s\", \"price\": %.2f, \"stock\": %d}",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getDouble("price"), rs.getInt("stock")));
                first = false;
            }
            json.append("\n]");
            out.print(json.toString());
        } catch (SQLException e) {
            log.warning("DB error: " + e.getMessage());
            out.print("{\"error\": \"internal error\"}");
        }
    }

    private void handleDetail(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String id = req.getParameter("id");
        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // This one uses prepared statement correctly
            PreparedStatement ps = conn.prepareStatement(
                "SELECT * FROM inventory WHERE id = ?");
            ps.setInt(1, Integer.parseInt(id));
            ResultSet rs = ps.executeQuery();

            if (rs.next()) {
                out.printf("{\"id\": %d, \"name\": \"%s\", \"description\": \"%s\", " +
                           "\"price\": %.2f, \"stock\": %d, \"category\": \"%s\"}\n",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getString("description"), rs.getDouble("price"),
                    rs.getInt("stock"), rs.getString("category"));
            } else {
                resp.sendError(404);
            }
        } catch (Exception e) {
            out.print("{\"error\": \"not found\"}");
        }
    }
}
